// PineWASM Desktop - Python bot generator
// Transpiles the SAME lowered AST the WASM pipeline uses into a standalone
// per-bar Python bot with identical ta semantics + broker emulator.
'use strict';
const { parse } = require('./parser');

const PY_LIB = `#!/usr/bin/env python3
# PineWASM Bot - generated by PineWASM Desktop v0.1
# Strategy: {TITLE}
# Same per-bar semantics as the PineWASM WASM engine (na = NaN, explicit history).
import argparse, json, math, os, sys, time, datetime

NAN = float('nan')
def isnan(x):
    try: return x != x
    except Exception: return True
def truthy(x):
    return (x == x) and (x != 0)
def fdiv(a, b):
    if isnan(a) or isnan(b) or b == 0: return NAN
    return a / b
def pmod(a, b):
    if isnan(a) or isnan(b) or b == 0: return NAN
    return a - math.trunc(a / b) * b
def mmax(*xs):
    if any(isnan(x) for x in xs): return NAN
    return max(xs)
def mmin(*xs):
    if any(isnan(x) for x in xs): return NAN
    return min(xs)
def hist(series, bar, k):
    if isnan(k): return NAN
    k = int(k)
    if k < 0 or bar - k < 0: return NAN
    return series[bar - k]

# ---------------- ta library (same formulas as WASM host) ----------------
class States:
    pass
def _st(states, key):
    if key not in states: states[key] = {'n': 0}
    return states[key]

def _win(series, bar, n):
    if bar - n + 1 < 0: return None
    w = series[bar - n + 1: bar + 1]
    if any(isnan(v) for v in w): return None
    return w

def _mean(w): return sum(w) / len(w)

def ta_sma(series, bar, n, st=None):
    w = _win(series, bar, n)
    return _mean(w) if w else NAN

def ta_wma(series, bar, n, st=None):
    w = _win(series, bar, n)
    if not w: return NAN
    num = den = 0.0
    for k, v in enumerate(w):
        wt = n - k
        num += v * wt; den += wt
    return num / den if den else NAN

def ta_stdev(series, bar, n, st=None):
    w = _win(series, bar, n)
    if not w: return NAN
    m = _mean(w)
    return math.sqrt(sum((v - m) ** 2 for v in w) / n)

def _rma_step(s, v, n):
    alpha = 1.0 / n
    if isnan(v):
        return s['v'] if s['n'] > 0 else NAN
    if s['n'] < n:
        s['sum'] = s.get('sum', 0.0) + v
        s['n'] += 1
        if s['n'] < n: return NAN
        s['v'] = s['sum'] / n
        return s['v']
    s['v'] = alpha * v + (1 - alpha) * s['v']
    return s['v']

def _ema_step(s, v, n):
    alpha = 2.0 / (n + 1)
    if isnan(v):
        return s['v'] if s['n'] > 0 else NAN
    if s['n'] < n:
        s['sum'] = s.get('sum', 0.0) + v
        s['n'] += 1
        if s['n'] < n: return NAN
        s['v'] = s['sum'] / n
        return s['v']
    s['v'] = alpha * v + (1 - alpha) * s['v']
    return s['v']

def ta_ema(series, bar, n, states, sid):
    return _ema_step(_st(states, 'e' + str(sid)), series[bar], n)

def ta_rma(series, bar, n, states, sid):
    return _rma_step(_st(states, 'r' + str(sid)), series[bar], n)

def ta_rsi(series, bar, n, states, sid):
    su = _st(states, 'rsiU' + str(sid)); sd = _st(states, 'rsiD' + str(sid))
    if bar < 1: return NAN
    prev = series[bar - 1]
    if isnan(prev): return NAN
    chg = series[bar] - prev
    up = chg if chg > 0 else 0.0
    dn = -chg if chg < 0 else 0.0
    u = _rma_step(su, up, n); d = _rma_step(sd, dn, n)
    if isnan(u) or isnan(d): return NAN
    if d == 0: return 100.0 if u > 0 else NAN
    rs = u / d
    return 100.0 - 100.0 / (1.0 + rs)

def ta_tr(H, L, C, bar):
    tr0 = H[bar] - L[bar]
    if bar == 0: return tr0
    pc = C[bar - 1]
    if isnan(pc): return tr0
    return max(tr0, abs(H[bar] - pc), abs(L[bar] - pc))

def ta_atr(H, L, C, bar, n, states, sid):
    return _rma_step(_st(states, 'atr' + str(sid)), ta_tr(H, L, C, bar), n)

def ta_highest(series, bar, n, st=None):
    w = _win(series, bar, n)
    return max(w) if w else NAN

def ta_lowest(series, bar, n, st=None):
    w = _win(series, bar, n)
    return min(w) if w else NAN

def ta_change(series, bar, st=None):
    if bar < 1: return NAN
    return series[bar] - series[bar - 1]

def ta_mom(series, bar, n, st=None):
    if bar - n < 0: return NAN
    return series[bar] - series[bar - n]

def ta_crossover(a, b, bar, st=None):
    if bar < 1: return 0.0
    return 1.0 if (a[bar] > b[bar] and a[bar - 1] <= b[bar - 1]) else 0.0

def ta_crossunder(a, b, bar, st=None):
    if bar < 1: return 0.0
    return 1.0 if (a[bar] < b[bar] and a[bar - 1] >= b[bar - 1]) else 0.0

def ta_cum(series, bar, states, sid):
    s = _st(states, 'c' + str(sid))
    v = series[bar]
    if not isnan(v): s['s'] = s.get('s', 0.0) + v
    return s.get('s', 0.0)

def ta_valuewhen(cond, src, bar, occ, st=None):
    cnt = 0
    for b in range(bar, -1, -1):
        c = cond[b]
        if truthy(c):
            if cnt == occ: return src[b]
            cnt += 1
    return NAN

# ---------------- broker (same rules as WASM engine) ----------------
class Broker:
    def __init__(self, O, H, L, C, T, meta, cfg):
        self.O, self.H, self.L, self.C, self.T = O, H, L, C, T
        self.meta = meta
        self.capital = float(cfg.get('capital', meta.get('capital', 100000)))
        self.cash = self.capital
        self.qty = 0.0
        self.avg = NAN
        self.entry_sid = -1
        self.pend_mkt = []
        self.pend_close = []
        self.exits = {}
        self.equity = []
        self.trades = []
        self.open_trade = None
        self.events = []
        self.pyramiding = meta.get('pyramiding', 0)

    def _commission(self, notional):
        cv = self.meta.get('commission_value', 0.0)
        c = cv if self.meta.get('commission_type') == 1 else notional * cv / 100.0
        self.cash -= c

    def _close(self, pxl, bar, reason):
        if self.qty == 0: return
        d = 1 if self.qty > 0 else -1
        q = abs(self.qty)
        pnl = d * (pxl - self.avg) * q
        self._commission(abs(q * pxl))
        if self.open_trade:
            self.open_trade.update(exitBar=bar, exitPx=pxl, exitTime=self.T[bar], pnl=pnl, reason=reason)
            self.trades.append(self.open_trade)
            self.open_trade = None
        self.cash += pnl
        self.qty = 0.0
        self.avg = NAN
        self.entry_sid = -1

    def _size(self, pxl):
        val = float(self.meta.get('default_qty_value', 10))
        if self.meta.get('default_qty_type') == 1:
            return abs(val)
        eq = self.cash + self.qty * pxl
        return (eq * val / 100.0) / pxl

    def _open(self, d, pxl, bar, sid, qty=None):
        q = qty if qty is not None else self._size(pxl)
        if not (q > 0): return
        self._commission(abs(q * pxl))
        self.qty = d * q
        self.avg = pxl
        self.entry_sid = sid
        self.open_trade = dict(dir=d, entryBar=bar, entryTime=self.T[bar], entryPx=pxl, qty=q, sid=sid)
        self.exits[sid] = {'stop': NAN, 'limit': NAN}

    def entry(self, bar, sid, d, qty=None):
        self.pend_mkt.append((bar, sid, 1 if d > 0 else -1, qty))

    def close(self, bar, sid):
        self.pend_close.append((bar, sid))

    def exit_(self, bar, sid, from_sid, stop, limit):
        self.exits[from_sid] = {'stop': stop, 'limit': limit}

    def pos(self): return self.qty
    def avgp(self): return self.avg if self.qty != 0 else NAN

    def step(self, bar):
        oo = self.O[bar]; hh = self.H[bar]; ll = self.L[bar]
        fills = [x for x in self.pend_mkt if x[0] < bar]
        self.pend_mkt = [x for x in self.pend_mkt if x[0] >= bar]
        closes = [x for x in self.pend_close if x[0] < bar]
        self.pend_close = [x for x in self.pend_close if x[0] >= bar]
        for (b0, s0) in closes:
            if s0 == -2 or (self.qty != 0 and self.entry_sid == s0):
                self._close(oo, bar, 'close')
                self.events.append(dict(bar=bar, type='close', px=oo))
        for (b0, s0, d, q) in fills:
            if d > 0:
                if self.qty < 0: self._close(oo, bar, 'reverse')
                if self.qty > 0 and self.entry_sid == s0: continue
                if self.qty == 0:
                    self._open(1, oo, bar, s0, q)
                    self.events.append(dict(bar=bar, type='long', px=oo, qty=q))
            else:
                if self.qty > 0: self._close(oo, bar, 'reverse')
                if self.qty < 0 and self.entry_sid == s0: continue
                if self.qty == 0:
                    self._open(-1, oo, bar, s0, q)
                    self.events.append(dict(bar=bar, type='short', px=oo, qty=q))
        if self.qty != 0:
            ex = self.exits.get(self.entry_sid)
            if ex:
                d = 1 if self.qty > 0 else -1
                sp, lp = ex['stop'], ex['limit']
                if d > 0:
                    if (not isnan(sp)) and ll <= sp:
                        pxl = min(oo, sp); self._close(pxl, bar, 'stop')
                        self.events.append(dict(bar=bar, type='stop', px=pxl))
                    elif (not isnan(lp)) and hh >= lp:
                        pxl = max(oo, lp); self._close(pxl, bar, 'limit')
                        self.events.append(dict(bar=bar, type='limit', px=pxl))
                else:
                    if (not isnan(sp)) and hh >= sp:
                        pxl = max(oo, sp); self._close(pxl, bar, 'stop')
                        self.events.append(dict(bar=bar, type='stop', px=pxl))
                    elif (not isnan(lp)) and ll <= lp:
                        pxl = min(oo, lp); self._close(pxl, bar, 'limit')
                        self.events.append(dict(bar=bar, type='limit', px=pxl))

    def mark(self, bar):
        self.equity.append(self.cash + self.qty * self.C[bar])

    def finish(self):
        last = len(self.C) - 1
        if self.qty != 0:
            self._close(self.C[last], last, 'end')
            self.events.append(dict(bar=last, type='end', px=self.C[last]))
        return self

def stats_of(b):
    eq = b.equity
    peak = float('-inf'); mdd = 0.0
    for v in eq:
        if v > peak: peak = v
        if peak > 0:
            dd = (peak - v) / peak
            if dd > mdd: mdd = dd
    wins = [t for t in b.trades if t['pnl'] > 0]
    losses = [t for t in b.trades if t['pnl'] <= 0]
    gw = sum(t['pnl'] for t in wins)
    gl = abs(sum(t['pnl'] for t in losses))
    net = b.cash - b.capital
    return dict(
        netProfit=net, netProfitPct=net / b.capital * 100.0, finalEquity=b.cash,
        trades=len(b.trades),
        winRate=(len(wins) / len(b.trades)) if b.trades else 0.0,
        profitFactor=(gw / gl) if gl > 0 else (999.0 if gw > 0 else 0.0),
        maxDDPct=mdd * 100.0,
        avgTrade=(net / len(b.trades)) if b.trades else 0.0,
    )

# ------- data io -------
def load_csv(path):
    import csv
    O, H, L, C, V, T = [], [], [], [], [], []
    with open(path, newline='') as f:
        r = csv.reader(f)
        rows = [row for row in r if row and any(c.strip() for c in row)]
    if rows and not any(c.replace('.', '').replace('-', '').isdigit() for c in rows[0][:1]):
        rows = rows[1:]
    for row in rows:
        try:
            ts, o, h, l, c, v = row[0], float(row[1]), float(row[2]), float(row[3]), float(row[4]), float(row[5]) if len(row) > 5 else 0.0
        except Exception:
            continue
        if '-' in str(ts) or ':' in str(ts):
            import datetime as dt
            try:
                ts = dt.datetime.fromisoformat(str(ts).replace('Z', '+00:00')).timestamp()
            except Exception:
                ts = dt.datetime.fromisoformat(str(ts)).timestamp()
        else:
            ts = float(ts)
            if ts > 1e12: ts = ts / 1000.0
        T.append(ts); O.append(o); H.append(h); L.append(l); C.append(c); V.append(v)
    return dict(O=O, H=H, L=L, C=C, V=V, T=T)

def fetch_okx(inst_id, bar='15m', limit=300):
    import urllib.request
    url = f"https://www.okx.com/api/v5/market/candles?instId={inst_id}&bar={bar}&limit={min(limit,300)}"
    with urllib.request.urlopen(url, timeout=15) as r:
        d = json.loads(r.read().decode())
    rows = d.get('data', [])[::-1]
    T = [int(r0[0]) / 1000.0 for r0 in rows]
    O = [float(r0[1]) for r0 in rows]
    H = [float(r0[2]) for r0 in rows]
    L = [float(r0[3]) for r0 in rows]
    C = [float(r0[4]) for r0 in rows]
    V = [float(r0[5]) for r0 in rows]
    return dict(O=O, H=H, L=L, C=C, V=V, T=T)

def webhook(url, payload):
    if not url: return False
    try:
        import urllib.request
        req = urllib.request.Request(url, data=json.dumps(payload).encode(), headers={'Content-Type': 'application/json'})
        with urllib.request.urlopen(req, timeout=10) as r:
            return 200 <= r.status < 300
    except Exception as e:
        print('webhook error:', e, file=sys.stderr)
        return False
`;

function pyStr(s) { return JSON.stringify(String(s == null ? '' : s)); }
function pyNum(v) {
  if (v == null || Number.isNaN(v)) return 'NAN';
  if (!Number.isFinite(v)) return v > 0 ? "float('inf')" : "float('-inf')";
  return String(v);
}

class PyEmitter {
  constructor(ctx, prog) {
    this.ctx = ctx; this.prog = prog;
    this.L = []; this.sid = 0; this.pid = 0;
    this.seriesSeen = new Set();
  }
  emit(line) { this.L.push(line); }
  seriesName(n) { return `S[${pyStr(n)}]`; }
  // expression compiler -> python string; preLines emitted before enclosing statement
  expr(e, pre) {
    if (!e) return 'NAN';
    switch (e.k) {
      case 'num': return pyNum(e.v);
      case 'na': return 'NAN';
      case 'str': return pyStr(e.v);
      case 'enum': {
        const d = dottedName(e);
        if (d === 'math.pi') return 'math.pi';
        if (d === 'math.e') return 'math.e';
        return String(valOfEnum(d));
      }
      case 'neg': return `(-${this.expr(e.e, pre)})`;
      case 'not': return `(0.0 if truthy(${this.expr(e.e, pre)}) else 1.0)`;
      case 'and': return `(1.0 if (truthy(${this.expr(e.l, pre)}) and truthy(${this.expr(e.r, pre)})) else 0.0)`;
      case 'or': return `(1.0 if (truthy(${this.expr(e.l, pre)}) or truthy(${this.expr(e.r, pre)})) else 0.0)`;
      case 'bin': {
        const L = this.expr(e.l, pre), R = this.expr(e.r, pre);
        switch (e.op) {
          case '+': return `(${L} + ${R})`;
          case '-': return `(${L} - ${R})`;
          case '*': return `(${L} * ${R})`;
          case '/': return `fdiv(${L}, ${R})`;
          case '%': return `pmod(${L}, ${R})`;
          case '==': return `(1.0 if ${L} == ${R} else 0.0)`;
          case '!=': return `(1.0 if ${L} != ${R} else 0.0)`;
          case '<': return `(1.0 if ${L} < ${R} else 0.0)`;
          case '<=': return `(1.0 if ${L} <= ${R} else 0.0)`;
          case '>': return `(1.0 if ${L} > ${R} else 0.0)`;
          case '>=': return `(1.0 if ${L} >= ${R} else 0.0)`;
        }
        return 'NAN';
      }
      case 'ter': return `(${this.expr(e.a, pre)} if truthy(${this.expr(e.c, pre)}) else ${this.expr(e.b, pre)})`;
      case 'ident': return this.ident(e.name, pre);
      case 'hist': {
        if (e.e.k === 'ident') {
          const n = e.e.name;
          const arr = this.builtinOrSeries(n);
          return `hist(${arr}, bar, ${this.expr(e.idx, pre)})`;
        }
        return 'NAN';
      }
      case 'call': return this.call(e, pre);
      default: return 'NAN';
    }
  }
  builtinOrSeries(n) {
    const map = { open: 'O_', high: 'H_', low: 'L_', close: 'C_', volume: 'V_', time: 'T_', hl2: 'H2_' };
    if (map[n]) return map[n];
    this.touchSeries(n);
    return this.seriesName(n);
  }
  touchSeries(n) { this.seriesSeen.add(n); }
  ident(n, pre) {
    if (n === 'bar_index') return 'float(bar)';
    if (n === 'last_bar_index') return 'float(len(C_) - 1)';
    if (n === 'true') return '1.0';
    if (n === 'false') return '0.0';
    if (n === 'na') return 'NAN';
    if (n === 'hlc3') return '((H_[bar] + L_[bar] + C_[bar]) / fdiv(3.0,1.0))';
    if (n === 'ohlc4') return '(O_[bar] + H_[bar] + L_[bar] + C_[bar]) / 4.0';
    if (n === 'strategy.position_size') return 'broker.pos()';
    if (n === 'strategy.position_avg_price') return 'broker.avgp()';
    const map = { open: 'O_[bar]', high: 'H_[bar]', low: 'L_[bar]', close: 'C_[bar]', volume: 'V_[bar]', time: 'T_[bar]', hl2: 'H2_[bar]' };
    if (map[n]) return map[n];
    this.touchSeries(n);
    return `${this.seriesName(n)}[bar]`;
  }
  materialize(e, pre) {
    if (e.k === 'ident') {
      const map = { open: 'O_', high: 'H_', low: 'L_', close: 'C_', volume: 'V_', time: 'T_', hl2: 'H2_' };
      if (map[e.name]) return map[e.name];
      if (this.ctx.seriesIdx.has(e.name)) return this.seriesName(e.name);
    }
    const tname = `tm${this.ctx.site++}_t`;
    const nm = tname;
    this.touchSeries(nm);
    this.ctx.hoistNaFill.push(nm);
    pre.push(`${this.seriesName(nm)}[bar] = ${this.expr(e, pre)}`);
    return this.seriesName(nm);
  }
  call(e, pre) {
    const ctx = this.ctx;
    const n = e.name;
    const A = (i) => this.expr(e.args && e.args[i], pre);
    const S0 = (i) => this.materialize(e.args && e.args[i], pre);
    if (/^input\./.test(n)) {
      const type = n.split('.')[1];
      let defval = e.args[0] ? constVal(e.args[0]) : (e.kw.defval ? constVal(e.kw.defval) : 0);
      const title = (e.args[1] && e.args[1].k === 'str') ? e.args[1].v : (e.kw.title && e.kw.title.k === 'str' ? e.kw.title.v : `input${ctx.inputs.length}`);
      const minval = e.kw.minval && e.kw.minval.k === 'num' ? e.kw.minval.v : null;
      const maxval = e.kw.maxval && e.kw.maxval.k === 'num' ? e.kw.maxval.v : null;
      let ii = ctx.inputs.findIndex(x => x.title === title && x.type === type);
      if (ii < 0) { ii = ctx.inputs.length; ctx.inputs.push({ idx: ii, type, defval, title, minval, maxval }); }
      if (type === 'string') return pyStr(defval);
      if (type === 'source') return 'C_[bar]';
      return `cfg[${pyStr(title)}]`;
    }
    if (n === 'na' && e.args && e.args.length) return `(1.0 if isnan(${A(0)}) else 0.0)`;
    if (n === 'nz') return `(${A(1) || '0.0'} if isnan(${A(0)}) else ${A(0)})`;
    if (n === 'math.abs') return `abs(${A(0)})`;
    if (n === 'math.floor') return `math.floor(${A(0)})`;
    if (n === 'math.ceil') return `math.ceil(${A(0)})`;
    if (n === 'math.sqrt') return `math.sqrt(${A(0)}) if ${A(0)} >= 0 else NAN`;
    if (n === 'math.round') {
      if (e.args[1]) {
        const m = `(math.pow(10.0, ${this.expr(e.args[1], pre)}))`;
        const X = this.expr(e.args[0], pre);
        return `(fdiv(float(round((${X}) * (${m}))), (${m})))`;
      }
      const X = this.expr(e.args[0], pre);
      return `(NAN if isnan(${X}) else float(round(${X})))`;
    }
    if (n === 'math.max') return `mmax(${(e.args || []).map(a => this.expr(a, pre)).join(', ')})`;
    if (n === 'math.min') return `mmin(${(e.args || []).map(a => this.expr(a, pre)).join(', ')})`;
    if (n === 'math.sum') return `(${(e.args || []).map(a => this.expr(a, pre)).join(' + ')})`;
    if (n === 'math.avg') return `((( ${(e.args || []).map(a => this.expr(a, pre)).join(' + ')}) ) / ${e.args.length || 1}.0)`;
    if (n === 'math.pow') return `math.pow(${A(0)}, ${A(1)})`;
    if (n === 'math.log') return `math.log(${A(0)})`;
    if (n === 'math.exp') return `math.exp(${A(0)})`;
    if (n === 'math.sign') return `(1.0 if ${A(0)} > 0 else (-1.0 if ${A(0)} < 0 else 0.0))`;
    if (n === 'int') {
      // python int(nan) raises; guard
      return `(NAN if isnan(${A(0)}) else float(int(${A(0)})))`;
    }
    if (n === 'float') return A(0) || 'NAN';
    const sidAlloc = () => ctx.stateCount++;
    if (n === 'ta.sma') return `ta_sma(${S0(0)}, bar, int(${A(1)}))`;
    if (n === 'ta.ema') return `ta_ema(${S0(0)}, bar, int(${A(1)}), STATES, ${sidAlloc()})`;
    if (n === 'ta.rma') return `ta_rma(${S0(0)}, bar, int(${A(1)}), STATES, ${sidAlloc()})`;
    if (n === 'ta.wma') return `ta_wma(${S0(0)}, bar, int(${A(1)}))`;
    if (n === 'ta.rsi') return `ta_rsi(${S0(0)}, bar, int(${A(1) || 14}), STATES, ${sidAlloc()})`;
    if (n === 'ta.tr' || n === 'ta.trueRange') return `ta_tr(H_, L_, C_, bar)`;
    if (n === 'ta.atr') return `ta_atr(H_, L_, C_, bar, int(${A(0) || 14}), STATES, ${sidAlloc()})`;
    if (n === 'ta.stdev') return `ta_stdev(${S0(0)}, bar, int(${A(1)}))`;
    if (n === 'ta.highest') return `ta_highest(${S0(0)}, bar, int(${A(1)}))`;
    if (n === 'ta.lowest') return `ta_lowest(${S0(0)}, bar, int(${A(1)}))`;
    if (n === 'ta.change') return `ta_change(${S0(0)}, bar)`;
    if (n === 'ta.mom') return `ta_mom(${S0(0)}, bar, int(${A(1)}))`;
    if (n === 'ta.cum') return `ta_cum(${S0(0)}, bar, STATES, ${sidAlloc()})`;
    if (n === 'ta.crossover') return `ta_crossover(${S0(0)}, ${S0(1)}, bar)`;
    if (n === 'ta.crossunder') return `ta_crossunder(${S0(0)}, ${S0(1)}, bar)`;
    if (n === 'ta.cross') return `ta_crossover(${S0(0)}, ${S0(1)}, bar)`;
    if (n === 'ta.valuewhen') return `ta_valuewhen(${S0(0)}, ${S0(1)}, bar, int(${A(2)}))`;
    ctx.errs.push({ line: e.line || 0, msg: 'pygen: unsupported function ' + n });
    return 'NAN';
  }
  // statements
  stmt(s, ind) {
    const pad = '    '.repeat(ind);
    if (s.kind === 'declare' || s.kind === 'assign') {
      const ctx = this.ctx;
      if (s.kind === 'declare') {
        ctx.addSeries(s.name, s.persist);
        this.touchSeries(s.name);
      }
      const pre = [];
      const v = this.expr(s.expr, pre);
      for (const p of pre) this.emit(pad + p);
      if (s.kind === 'declare' && s.persist) {
        const fi = ctx.persistIdx.get(s.name);
        this.emit(pad + `if not PFLAG[${pyStr(s.name)}]:`);
        this.emit(pad + `    ${this.seriesName(s.name)}[bar] = ${v}`);
        this.emit(pad + `    PFLAG[${pyStr(s.name)}] = True`);
      } else {
        this.emit(pad + `${this.seriesName(s.name)}[bar] = ${v}`);
      }
      return;
    }
    if (s.kind === 'if') {
      const pre = [];
      const c = this.expr(s.cond, pre);
      for (const p of pre) this.emit(pad + p);
      this.emit(pad + `if truthy(${c}):`);
      if (!s.then || !s.then.length) this.emit(pad + `    pass`);
      else for (const ss of s.then) this.stmt(ss, ind + 1);
      if (s.else && s.else.length) {
        this.emit(pad + `else:`);
        for (const ss of s.else) this.stmt(ss, ind + 1);
      }
      return;
    }
    if (s.kind === 'for') {
      const pre = [];
      const fromV = this.expr(s.from, pre);
      const toV = this.expr(s.to, pre);
      const byV = s.by ? this.expr(s.by, pre) : '1.0';
      for (const p of pre) this.emit(pad + p);
      const lv = `_iv${this.loopN = (this.loopN || 0) + 1}`;
      this.loops = this.loops || new Map();
      this.loops.set(s.ivar, lv);
      const prev = this.loopVar;
      this.loopVar = { name: s.ivar, local: lv };
      this.emit(pad + `${lv} = ${fromV}`);
      this.emit(pad + `while (not isnan(${lv})) and ${lv} <= ${toV} + 1e-12:`);
      if (!s.body || !s.body.length) this.emit(pad + `    pass`);
      else {
        for (const ss of s.body) {
          // redirect ivar reads to local
          this.stmtFor(ss, ind + 1, s.ivar, lv);
        }
        this.emit(pad + `    ${lv} = ${lv} + ${byV}`);
      }
      this.loopVar = prev;
      return;
    }
    if (s.kind === 'call') { this.callStmt(s.expr, s.line, ind); return; }
  }
  stmtFor(s, ind, ivarName, lv) {
    // temporarily map ivar ident to local scalar
    const save = this.identHook;
    this.identHook = (n) => (n === ivarName ? lv : null);
    this.stmt(s, ind);
    this.identHook = save;
  }
  callStmt(e, line, ind) {
    const pad = '    '.repeat(ind);
    const ctx = this.ctx;
    const name = e && e.k === 'call' ? e.name : null;
    if (!name) { const pre = []; this.expr(e, pre); for (const p of pre) this.emit(pad + p); return; }
    const pre = [];
    const arg = (i) => this.expr(e.args && e.args[i], pre);
    for (const p of pre) this.emit(pad + p);
    if (name === 'plot') {
      const pid = this.ctx.plotSeq++;
      const title = (e.args[1] && e.args[1].k === 'str') ? e.args[1].v : 'plot' + pid;
      this.ctx.plots.push({ pid, title, colorId: 1 });
      this.emit(pad + `PLOTS.setdefault(${pid}, [NAN] * nbars)[bar] = ${arg(0)}`);
      return;
    }
    if (name === 'plotshape' || name === 'plotchar') {
      const v = arg(0);
      this.emit(pad + `if truthy(${v}): MARKERS.append((bar, 1))`);
      return;
    }
    if (name === 'strategy.entry') {
      const sid = this.strId(e.args[0]);
      let dir = '1.0';
      if (e.args[1] && e.args[1].k === 'enum') { const dv = valOfEnum(dottedName(e.args[1])); dir = String(Number.isFinite(dv) ? dv : 1); }
      if (e.kw.qty || (e.args && e.args[2])) {
        const q = e.kw.qty ? this.expr(e.kw.qty, pre) : arg(2);
        this.emit(pad + `broker.entry(bar, ${sid}, ${dir}, abs(${q}))`);
      } else this.emit(pad + `broker.entry(bar, ${sid}, ${dir})`);
      return;
    }
    if (name === 'strategy.close') {
      this.emit(pad + `broker.close(bar, ${this.strId(e.args[0])})`);
      return;
    }
    if (name === 'strategy.close_all') {
      this.emit(pad + `broker.close(bar, -2)`);
      return;
    }
    if (name === 'strategy.exit') {
      const sid = this.strId(e.args[0]);
      const fromSid = e.kw.from_entry ? this.strId(e.kw.from_entry) : sid;
      const stop = e.kw.stop ? this.expr(e.kw.stop, pre) : 'NAN';
      const limit = e.kw.limit ? this.expr(e.kw.limit, pre) : 'NAN';
      this.emit(pad + `broker.exit_(bar, ${sid}, ${fromSid}, ${stop}, ${limit})`);
      return;
    }
    if (name === 'hline' || name === 'bgcolor' || name === 'fill' || name === 'alertcondition' || name === 'barcolor') return;
    if (name === 'indicator' || name === 'strategy') return;
    ctx.warns.push({ line: line || 0, msg: 'pygen: statement ignored ' + name });
  }
  strId(e) {
    // intern string ids same way as compile.js
    if (e && e.k === 'str') return this.ctx.intern(e.v);
    if (e && e.k === 'ident') return this.ctx.intern(e.name);
    return this.ctx.intern('anon');
  }
}

function dottedName(e) {
  if (!e) return '';
  if (e.k === 'enum') return dottedName(e.base) + '.' + e.name;
  if (e.k === 'ident') return e.name;
  return '';
}
function ctxOfNothing() {
  return { title: 'PineWASM Script', overlay: true, isStrategy: false, default_qty_type: 0,
    default_qty_value: 10, commission_type: 0, commission_value: 0, capital: 100000, pyramiding: 0 };
}
function truthyConst(e) {
  return !!((e.k === 'num' && e.v !== 0) || (e.k === 'ident' && e.name === 'true'));
}
function pyJson(obj) {
  return JSON.stringify(obj, null, 2)
    .replace(/\btrue\b/g, 'True')
    .replace(/\bfalse\b/g, 'False')
    .replace(/\bnull\b/g, 'None');
}
function valOfEnum(d) {
  const m = { 'strategy.long': 1, 'strategy.short': -1 };
  if (m[d] !== undefined) return m[d];
  if (/^color\./.test(d)) { const map = { red: 0, green: 1, blue: 2, white: 3, gray: 4, grey: 4, lime: 1, orange: 1, maroon: 0, aqua: 2, teal: 2, navy: 2, yellow: 3, silver: 4, purple: 4, fuchsia: 4, black: 3 }; return map[d.split('.')[1]] ?? 4; }
  return 0;
}
function constVal(e) {
  if (e.k === 'num') return e.v;
  if (e.k === 'ident' && e.name === 'true') return 1;
  if (e.k === 'ident' && e.name === 'false') return 0;
  return 0;
}

function generateBot(src) {
  const { _internals } = require('./compile');
  const { Ctx, lowerList } = _internals;
  const errs = [];
  const ast = parse(src, errs);
  // extract declaration meta (same as compile.js)
  const meta0 = ctxOfNothing();
  for (const s of ast) {
    if (s.kind === 'call' && s.expr && /^(indicator|strategy)$/.test(s.expr.name)) {
      const a = s.expr, m = meta0;
      if (a.args[0] && a.args[0].k === 'str') m.title = a.args[0].v;
      m.isStrategy = a.name === 'strategy';
      m.overlay = a.kw.overlay ? truthyConst(a.kw.overlay) : m.isStrategy;
      if (a.kw.default_qty_type && a.kw.default_qty_type.k === 'enum') m.default_qty_type = valOfEnum(dottedName(a.kw.default_qty_type));
      if (a.kw.default_qty_value && a.kw.default_qty_value.k === 'num') m.default_qty_value = a.kw.default_qty_value.v;
      if (a.kw.commission_type && a.kw.commission_type.k === 'enum') {
        const d = dottedName(a.kw.commission_type);
        m.commission_type = d === 'strategy.commission.cash_per_order' ? 1 : 0;
      }
      if (a.kw.commission_value && a.kw.commission_value.k === 'num') m.commission_value = a.kw.commission_value.v;
      if (a.kw.capital && a.kw.capital.k === 'num') m.capital = a.kw.capital.v;
      if (a.kw.pyramiding && a.kw.pyramiding.k === 'num') m.pyramiding = a.kw.pyramiding.v;
    }
  }
  const funcs = {};
  for (const s of ast) if (s.kind === 'func') funcs[s.name] = s;
  const ctx = new Ctx();
  Object.assign(ctx.meta, meta0);
  const prog = lowerList(ast.filter(s => s.kind !== 'func'), funcs, ctx, new Set());
  const em = new PyEmitter(ctx, prog);
  const meta = ctx.meta;
  for (const s of prog) em.stmt(s, 2);

  // inputs
  const inputs = ctx.inputs.map(inp => ({
    name: inp.title, type: inp.type, def: inp.type === 'string' ? String(inp.defval) : (inp.defval ?? 0),
    min: inp.minval, max: inp.maxval,
  }));
  const metaOut = {
    title: meta.title, isStrategy: meta.isStrategy, overlay: meta.overlay,
    default_qty_type: meta.default_qty_type, default_qty_value: meta.default_qty_value,
    commission_type: meta.commission_type, commission_value: meta.commission_value,
    capital: meta.capital, pyramiding: meta.pyramiding,
  };
  const cfgJson = {};
  for (const i of inputs) cfgJson[i.name] = i.def;
  cfgJson['capital'] = metaOut.capital;

  const bodyCode = em.L.join('\n');
  const persistList = [...ctx.persistIdx.keys()].map(pyStr).join(', ');
  const naFillList = [...new Set(ctx.hoistNaFill)].map(pyStr).join(', ');
  const allNames = new Set([...ctx.series.map(s => s.name), ...em.seriesSeen]);
  const seriesInit = `[${[...allNames].map(pyStr).join(', ')}]`;
  cfgJson['symbol'] = 'BTC-USDT-SWAP';
  cfgJson['timeframe'] = '15m';
  cfgJson['webhook_url'] = '';

  const lib = PY_LIB
    .replace('{TITLE}', metaOut.title)
    .replace('{META}', pyNum(metaOut.default_qty_value || 10));

  const bot = `${lib}

# ---------------- generated strategy: ${metaOut.title.replace(/\\n/g, ' ')} ----------------
META = ${pyJson(metaOut)}
CONFIG_DEFAULTS = ${pyJson(cfgJson)}
PERSIST_VARS = [${persistList}]
NA_FILL_VARS = [${naFillList}]
SERIES_ALL = ${seriesInit}

def run(data, cfg):
    O_, H_, L_, C_, V_, T_ = data['O'], data['H'], data['L'], data['C'], data['V'], data['T']
    H2_ = [(h + l) / 2.0 for h, l in zip(H_, L_)]
    nbars = len(C_)
    S = {}          # series by name -> list
    for _nm in SERIES_ALL:
        S[_nm] = [NAN] * nbars
    PFLAG = {}      # persist init flags
    STATES = {}     # ta call-site state
    PLOTS = {}      # pid -> list
    MARKERS = []    # (bar, loc)
    SID = {}
    def SIDF(name):
        if name not in SID: SID[name] = len(SID)
        return SID[name]
    broker = Broker(O_, H_, L_, C_, T_, META, cfg)
    for bar in range(nbars):
        broker.step(bar)
        for nm in NA_FILL_VARS:
            if nm in S: S[nm][bar] = NAN
        for nm in PERSIST_VARS:
            if nm in S and PFLAG.get(nm) and bar > 0:
                S[nm][bar] = S[nm][bar - 1]
${''
}
${bodyCode}
        broker.mark(bar)
    broker.finish()
    return dict(broker=broker, plots=PLOTS, markers=MARKERS, stats=stats_of(broker))

def main():
    ap = argparse.ArgumentParser(description='PineWASM Bot - ${metaOut.title.replace(/"/g, '')}')
    ap.add_argument('--csv', help='csv file: time,open,high,low,close,volume')
    ap.add_argument('--okx', help='okx instrument, e.g. BTC-USDT-SWAP')
    ap.add_argument('--tf', default=CONFIG_DEFAULTS.get('timeframe', '15m'))
    ap.add_argument('--limit', type=int, default=300)
    ap.add_argument('--live', action='store_true', help='poll last closed candle and fire signals')
    ap.add_argument('--interval', type=int, default=30, help='live poll seconds')
    ap.add_argument('--trades-csv', help='write trades csv')
    a = ap.parse_args()
    cfg = dict(CONFIG_DEFAULTS)
    webhook_url = (cfg.get('webhook_url') or '').strip()
    if a.csv: data = load_csv(a.csv)
    elif a.okx: data = fetch_okx(a.okx, a.tf, a.limit)
    else:
        print('need --csv or --okx'); sys.exit(1)
    if not a.live:
        r = run(data, cfg)
        st = r['stats']
        print('NETPCT', round(st['netProfitPct'], 4))
        print('TRADES', st['trades'])
        print('WINRATE', round(st['winRate'] * 100, 2))
        print('PF', round(st['profitFactor'], 3))
        print('MAXDD', round(st['maxDDPct'], 3))
        if a.trades_csv:
            import csv
            with open(a.trades_csv, 'w', newline='') as f:
                w = csv.writer(f)
                w.writerow(['dir','entryTime','entryPx','qty','exitTime','exitPx','pnl','reason'])
                for t in r['broker'].trades:
                    w.writerow([t['dir'], t['entryTime'], t['entryPx'], t['qty'], t.get('exitTime'), t.get('exitPx'), round(t.get('pnl', 0.0), 6), t.get('reason')])
        return
    # live: rolling window per bar
    last_fired_bar = -1
    while True:
        try:
            d = fetch_okx(cfg['symbol'], cfg.get('timeframe', '15m'), 300) if not a.okx else fetch_okx(a.okx, a.tf, a.limit)
            r = run(d, cfg)
            evs = [e for e in r['broker'].events if e['bar'] >= len(d['C']) - 3]
            for e in evs:
                if e['bar'] > last_fired_bar:
                    last_fired_bar = e['bar']
                    msg = f"{datetime.datetime.fromtimestamp(d['T'][e['bar']])} {e['type']} @ {e['px']}"
                    print(msg, flush=True)
                    if e['type'] in ('long', 'short', 'close'):
                        webhook(webhook_url, dict(action={'long': 'buy', 'short': 'sell'}.get(e['type'], 'close'), symbol=cfg.get('symbol'), qty=1, price=e['px']))
        except KeyboardInterrupt:
            break
        except Exception as e:
            print('live error:', e, file=sys.stderr)
        time.sleep(a.interval)

if __name__ == '__main__':
    main()
`;
  return { bot, meta: metaOut, inputs, errs: errs.concat(ctx.errs), warns: ctx.warns, symbols: ctx.strings };
}

module.exports = { generateBot };
